void InitWindow(frame_buffer Frame, const char *Title){
	App.Display = XOpenDisplay(NULL);
	XSetWindowAttributes SetAttributes = {0};
	App.Window = XCreateWindow(App.Display, XRootWindow(App.Display, 0), 0, 0, Frame.Width, Frame.Height, 0, 0, InputOutput, CopyFromParent, CWOverrideRedirect, &SetAttributes);
	App.WindowWidth = Frame.Width;
	App.WindowHeight = Frame.Height;
	XWindowAttributes WindowAttributes = {0};
	XGetWindowAttributes(App.Display, App.Window, &WindowAttributes);
	App.Image = XCreateImage(App.Display, WindowAttributes.visual, WindowAttributes.depth, ZPixmap, 0, (char *)Frame.Pixels, Frame.Width, Frame.Height, 32, Frame.Width*4);  
	App.WMDeleteWindow = XInternAtom(App.Display, "WM_DELETE_WINDOW", false);
	App.GC = XDefaultGC(App.Display, 0);

	XSizeHints Hints = {.min_width = Frame.Width, .min_height = Frame.Height, .max_height = Frame.Height, .max_width = Frame.Width, .flags = PMinSize | PMaxSize};
	XSetSizeHints(App.Display, App.Window, &Hints, XA_WM_NORMAL_HINTS);

	XSetWMProtocols(App.Display, App.Window, &App.WMDeleteWindow, 1);
	XStoreName(App.Display, App.Window, Title);
	XSelectInput(App.Display, App.Window, KeyPressMask | ExposureMask | ButtonPressMask | Button1MotionMask);
	XMapWindow(App.Display, App.Window);
	XSync(App.Display, false);
}

void DrawImage(){
	XPutImage(App.Display, App.Window, App.GC, App.Image, 0, 0, 0, 0, App.WindowWidth, App.WindowHeight);
	XSync(App.Display, false);
}

#define ABS(a) ((a) > 0? (a): (-(a)))
#define MAX(a, b) ((a) > (b)? (a): (b))
#define MIN(a, b) ((a) < (b)? (a): (b))
#define CLAMP(x, a, b) MAX(a, MIN(x, b))

f32 Ceil(f32 a){ return (f32)(s32)(a+1); }
f32 Floor(f32 a){ return (f32)(s32) a; }
f32 Fract(f32 a){ return a >= 0? a - Floor(a): a - Ceil(a-2); }

void RenderLine(frame_buffer Frame, v2s P0, v2s P1, s32 LineThickness, u32 Color){
	//TODO: find a way to make the bounding box smaller
	s32 StartX = MAX((P0.x - LineThickness), 0);
	s32 EndX = MIN(P1.x+LineThickness, Frame.Width);
	if(P0.x > P1.x){
		StartX = MAX((P1.x - LineThickness), 0);
		EndX = MIN(P0.x+LineThickness, Frame.Width);
	}

	s32 StartY = MAX((P0.y - LineThickness), 0);
	s32 EndY = MIN(P1.y+LineThickness, Frame.Width);
	if(P0.y > P1.y){
		StartY = MAX((P1.y - LineThickness), 0);
		EndY = MIN(P0.y+LineThickness, Frame.Width);
	}

	v2f P0N = (v2f){ .x = (f32)P0.x/ Frame.Width, .y = (f32)P0.y / Frame.Height };
	v2f P1N = (v2f){ .x = (f32)P1.x/ Frame.Width, .y = (f32)P1.y / Frame.Height };
	v2f P1N_P0N = (v2f){ .x = P1N.x - P0N.x, .y = P1N.y - P0N.y };
	f32 LengthSquaredP1N_P0N = P1N_P0N.x * P1N_P0N.x + P1N_P0N.y * P1N_P0N.y;
	f32 ThicknessSquared = (f32)(LineThickness*LineThickness) / (Frame.Width*Frame.Width + Frame.Height*Frame.Height);

	for(s32 y=StartY; y<=EndY; y++)
		for(s32 x=StartX; x<=EndX; x++){
			v2f P = (v2f){ .x = (f32)x / Frame.Width, .y = (f32)y / Frame.Height };
			v2f P_P0N = (v2f){ .x = P0N.x - P.x, .y = P0N.y - P.y };
			f32 CrossProduct = P_P0N.x * P1N_P0N.y - P_P0N.y * P1N_P0N.x;
			f32 DistSquared = (CrossProduct*CrossProduct) / LengthSquaredP1N_P0N;
			if(DistSquared <= ThicknessSquared)
				Frame.Pixels[y * Frame.Width + x] = Color;
		}
}

void RenderCircle(frame_buffer Frame, v2s Center, s32 Radius, u32 Color){
	s32 StartX = MAX(Center.x-Radius, 0);
	s32 EndX = MIN(Center.x+Radius, Frame.Width);
	s32 StartY = MAX(Center.y-Radius, 0);
	s32 EndY = MIN(Center.y+Radius, Frame.Height);
	for(s32 y=StartY; y<EndY; y++)
		for(s32 x=StartX; x<EndX; x++)
			if((y-Center.y)*(y-Center.y) + (x-Center.x)*(x-Center.x) <= Radius*Radius)
				Frame.Pixels[y * Frame.Width + x] = Color;
}

void RenderIntersections(frame_buffer Frame, v2s P0, v2s P1, Tile *WorldMap, s32 MapWidth, s32 MapHeight, u32 Color){
	//this is really stupid, TODO: redo all this nonsense
	s32 TileWidth = Frame.Width/MapWidth;
	s32 TileHeight = Frame.Width/MapHeight;
	f32 Slope = (f32)(P1.y - P0.y) / (P1.x - P0.x);
	s32 Offset = P1.y - Slope * P1.x;

	s32 ClosestX1 = 0, ClosestY1 = 0, ClosestX2 = 0, ClosestY2 = 0;

	if(P1.y > P0.y)
		for(f32 TileY = ((f32)P0.y/TileHeight); TileY < MapHeight; TileY++){
			s32 ClosestMapTileY = (s32)Floor(TileY);
			ClosestY1 = ClosestMapTileY*TileHeight;
			ClosestX1 = (ClosestY1 - Offset) / Slope;
			s32 ClosestMapTileX = CLAMP((s32)Floor(ClosestX1/TileWidth), 0, MapWidth); //Clamp cuz dividing by small Slope gives Large x
			Tile MapTile = WorldMap[ClosestMapTileY * MapWidth + ClosestMapTileX];
			if(MapTile) break;
		}
	else
		for(f32 TileY = ((f32)P0.y/TileHeight); TileY > 0; TileY--){
			s32 ClosestMapTileY = (s32)Floor(TileY)-1;
			ClosestY1 = ClosestMapTileY*TileHeight;
			ClosestX1 = (ClosestY1 - Offset) / Slope;
			s32 ClosestMapTileX = CLAMP((s32)Floor(ClosestX1/TileWidth), 0, MapWidth); //Clamp cuz dividing by small Slope gives Large x
			Tile MapTile = WorldMap[ClosestMapTileY * MapWidth + ClosestMapTileX];
			if(MapTile) break;
		}

	if(P1.x > P0.x)
		for(f32 TileX = ((f32)P0.x/TileWidth); TileX < MapWidth; TileX++){
			s32 ClosestMapTileX = (s32)Floor(TileX);
			ClosestX2 = ClosestMapTileX*TileWidth;
			ClosestY2 = ClosestX2 * Slope + Offset;
			s32 ClosestMapTileY = (s32)Floor(ClosestY2/TileWidth);
			Tile MapTile = WorldMap[ClosestMapTileY * MapWidth + ClosestMapTileX];
			if(MapTile) break;
		}
	else
		for(f32 TileX = ((f32)P0.x/TileWidth); TileX > 0 ; TileX--){
			s32 ClosestMapTileX = (s32)Floor(TileX);
			ClosestX2 = ClosestMapTileX * TileWidth;
			ClosestY2 = ClosestX2 * Slope + Offset;
			s32 ClosestMapTileY = (s32)Floor(ClosestY2/TileWidth);
			Tile MapTile = WorldMap[ClosestMapTileY * MapWidth + ClosestMapTileX];
			if(MapTile) break;
		}

	s32 ClosestY = 0, ClosestX = 0;
	if(P1.y > P0.y && P1.x > P0.x){
		ClosestY = MIN(ClosestY1, ClosestY2);
		ClosestX = MIN(ClosestX1, ClosestX2);
	}
	else if(P1.y > P0.y && P1.x < P0.x){
		ClosestY = MIN(ClosestY1, ClosestY2);
		ClosestX = MAX(ClosestX1, ClosestX2);
	}
	else if(P1.y < P0.y && P1.x > P0.x){
		ClosestY = MAX(ClosestY1, ClosestY2);
		ClosestX = MIN(ClosestX1, ClosestX2);
	}
	else if(P1.y < P0.y && P1.x < P0.x){
		ClosestY = MAX(ClosestY1, ClosestY2);
		ClosestX = MAX(ClosestX1, ClosestX2);
	}

	RenderCircle(Frame, V2s(ClosestX, ClosestY), 4, Color);
}

void RenderMap(frame_buffer Frame, Tile *WorldMap, s32 MapWidth, s32 MapHeight){
	s32 TileWidth = Frame.Width/MapWidth;
	s32 TileHeight = Frame.Width/MapHeight;
	s32 LineThickness = 2;

	static u32 MapToColor[TILE_COUNT] = { [TILE0] = 0x00181818, [TILE1] = 0x00458588, [TILE2] = 0x00D79921, [TILE3] = 0x0098971A, [TILE4] = 0x00CC241D, [TILE5] = 0x00A89984 };

	for(s32 Row=0; Row<MapHeight; Row++)
		for(s32 Column=0; Column<MapWidth; Column++){
			u32 Color = MapToColor[WorldMap[Row*MapWidth + Column]];
			for(s32 y=0; y<TileHeight; y++)
				for(s32 x=0; x<TileWidth; x++)
					Frame.Pixels[(y + Row*TileHeight)*Frame.Height + (x + Column*TileWidth)] = Color;
		}

	for(s32 x=0; x<TileWidth; x++)
		RenderLine(Frame, (v2s){ x*TileWidth, 0 }, (v2s){ x*TileWidth, Frame.Height }, LineThickness, 0x00282828);
	
	for(s32 y=0; y<TileHeight; y++)
		RenderLine(Frame, (v2s){ 0, y*TileHeight }, (v2s){ Frame.Width, y*TileHeight }, LineThickness, 0x00282828);
}

void RenderText(frame_buffer Frame, char *Text, u32 Length, v2s Pos, s32 Scale, u32 Color){
	s32 OffsetX = Pos.x;
	for(u32 i = 0; i < Length; i++){
		char c = Text[i];
		if(c == '\n'){
			Pos.y += GLYPH_HEIGHT*Scale;
			OffsetX = Pos.x;
			continue;
		}
		for(s32 y = 0; y < GLYPH_HEIGHT; y++)
			for(s32 x = 0; x < GLYPH_WIDTH; x++){
				u8 Row = BitmapFont[c*GLYPH_WIDTH + y];
				if(Row & (1 << x)){ //it's not that complicated i swear...
					for(s32 ScaleY = 0; ScaleY < Scale; ScaleY++)
						for(s32 ScaleX = 0; ScaleX < Scale; ScaleX++)
							Frame.Pixels[(Pos.y + y*Scale + ScaleY)*Frame.Width + (x*Scale + ScaleX + OffsetX)] = Color;
				}
			}
		OffsetX += GLYPH_WIDTH + GLYPH_GAP + Scale;
	}
}

